package com.gerenciadorrural.modules.farms.application;
import com.gerenciadorrural.modules.farms.domain.*; import com.gerenciadorrural.shared.tenancy.*; import org.springframework.stereotype.Service; import java.util.Objects;
@Service public class GetCurrentFarmProfile {private final TenantTransactionExecutor transactions;private final FarmProfileQueryRepository repository;public GetCurrentFarmProfile(TenantTransactionExecutor transactions,FarmProfileQueryRepository repository){this.transactions=transactions;this.repository=repository;}public FarmProfile execute(TenantContext context){Objects.requireNonNull(context,"O contexto de tenant é obrigatório");return transactions.execute(context,()->repository.findCurrent(context.tenantId(),context.farmId()).orElseThrow(FarmProfileNotAvailableException::new));}}
